import {mountFacilityMap} from './facility-map.js';
import {icon} from './icons.js';
import {testFacilities,testFacilityAssets,facilityKinds,facilityOwnership,getTestFacility,getFacilityAsset,facilitySources,facilityMapUrls,facilityAtlasRevision} from './test-facilities.js';

const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export const formatFacilityNumber=v=>Number(v)!==0&&Math.abs(Number(v))<.001?Number(v).toExponential(2):Number(v).toLocaleString('en-US',{maximumFractionDigits:4});
const n=formatFacilityNumber;
const link=(url,label,cls='')=>'<a class="'+cls+'" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+' ↗</a>';
const notional=a=>a?.geometry?.dimensionRole==='working-envelope'||a?.geometry?.representation==='wireframe-volume';
const roles={'published-chamber-dimensions':'Published chamber dimensions','published-room-dimensions':'Published room dimensions','published-vessel-dimensions':'Published vessel dimensions','chamber-interior':'Chamber interior','chamber-exterior':'Chamber exterior','working-envelope':'Published working envelope','table-surface':'Mounting tabletop','room-interior':'Room interior'};
const sourceIdsFor=a=>[...new Set([...(a.sourceIds||[]),...(a.geometry?.sourceIds||[]),...(a.envelope?.sourceIds||[]),...(a.door?.sourceIds||[]),...Object.values(a.limitSourceIds||{}).flat()])];
export function facilityDimensionsText(asset){
 const g=asset?.geometry,d=g?.dimensions;if(!d)return 'Public dimensions not recorded';
 if(g.type==='cylinder-horizontal')return 'Ø '+n(d.diameterM)+' × '+n(d.lengthM)+' m long';
 if(g.type==='cylinder-vertical')return 'Ø '+n(d.diameterM)+' × '+n(d.heightM??d.lengthM)+' m high';
 if(g.type==='shaker-round')return 'Ø '+n(d.diameterM)+' m tabletop';
 if(g.type==='shaker-square')return n(d.widthM)+' × '+n(d.depthM)+' m tabletop';
 return n(d.widthM)+' W × '+n(d.heightM)+' H × '+n(d.depthM)+' D m';
}
function envelopeText(e){if(!e)return 'Not published in this record';return e.shape==='cylinder'?'Ø '+n(e.diameterM)+' × '+n(e.lengthM)+' m '+(e.axis==='y'?'high':'long'):n(e.widthM)+' W × '+n(e.heightM)+' H × '+n(e.depthM)+' D m';}
const limitLabels={payloadKg:['Article mass','kg'],forceSineKN:['Sine force','kN'],forceRandomKN:['Random force','kN'],maxCgHeightM:['Maximum CG height','m'],temperatureMinK:['Minimum published temperature','K'],temperatureMaxK:['Maximum published temperature','K'],pressurePa:['Published pressure','Pa'],splDb:['Acoustic level','dB']};

export function mountFacilitiesAtlas(host,{view={},onState=()=>{},onPart=()=>{}}={}){
 const first=testFacilities[0];if(!first){host.textContent='The facilities catalog is unavailable.';return {destroy(){}};}
 let alive=true,ticket=0,viewer=null,mapCleanup=null;
 let selected=getTestFacility(view.facilityId)||first,asset=getFacilityAsset(view.facilityAssetId),surface=['3d','world','local'].includes(view.facilityView)?view.facilityView:'3d';
 if(asset?.facilityId!==selected.id)asset=testFacilityAssets.find(a=>a.facilityId===selected.id&&a.geometry)||testFacilityAssets.find(a=>a.facilityId===selected.id);
 const filters={query:'',country:'',ownership:'',capability:'',...view.facilityFilter};
 const settings={mode:'materials',cutaway:true,dimensions:true,person:true};
 const countries=[...new Set(testFacilities.map(f=>f.country))].sort();
 host.innerHTML='<section class="fa-workspace" aria-label="Test facilities atlas"><header class="fa-intro"><div><span class="fa-eyebrow">FACILITIES ATLAS</span><h2>Real places. Documented test systems.</h2><p>Explore public facility capabilities, inspect their dimensions in 3D, and locate each campus. Equipment keeps its documented size when used in the Parts navigator.</p></div><dl class="fa-totals"><div><dt>Facilities</dt><dd>'+testFacilities.length+'</dd></div><div><dt>Countries</dt><dd>'+countries.length+'</dd></div><div><dt>3D systems</dt><dd>'+testFacilityAssets.filter(a=>a.geometry).length+'</dd></div></dl></header><div class="fa-layout"><aside class="fa-browser"><label class="fa-search">Find a facility<input type="search" data-facility-query value="'+esc(filters.query)+'" placeholder="Campus, operator, city, capability…"></label><div class="fa-filters"><label>Country<select data-facility-filter="country"><option value="">All countries</option>'+countries.map(c=>'<option '+(filters.country===c?'selected ':'')+'value="'+esc(c)+'">'+esc(c)+'</option>').join('')+'</select></label><label>Operator type<select data-facility-filter="ownership"><option value="">All operators</option>'+Object.entries(facilityOwnership).map(([k,v])=>'<option '+(filters.ownership===k?'selected ':'')+'value="'+k+'">'+v+'</option>').join('')+'</select></label><label class="fa-wide">Capability<select data-facility-filter="capability"><option value="">All capabilities</option>'+Object.entries(facilityKinds).filter(([k])=>testFacilityAssets.some(a=>a.kind===k)).map(([k,v])=>'<option '+(filters.capability===k?'selected ':'')+'value="'+k+'">'+v+'</option>').join('')+'</select></label></div><div class="fa-result-meta"><span data-facility-count role="status"></span><button type="button" data-facility-clear>Reset filters</button></div><p class="fa-filter-note" data-facility-filter-note hidden></p><nav class="fa-list" aria-label="Test facilities" data-facility-list></nav></aside><article class="fa-article" data-facility-article></article></div><footer class="fa-atlas-foot">Public-source capability atlas · Reviewed '+esc(first.reviewed)+' · '+esc(facilityAtlasRevision)+'<br>Reconstructed equipment dimensions are evidence for an initial study. A campaign still needs a facility-approved article configuration, fixture, test specification, safety review, and schedule.</footer></section>';
 const find=s=>host.querySelector(s),article=find('[data-facility-article]');
 const filtered=()=>testFacilities.filter(f=>(!filters.country||f.country===filters.country)&&(!filters.ownership||f.ownership===filters.ownership)&&(!filters.capability||f.assets.some(a=>a.kind===filters.capability))&&filters.query.trim().toLowerCase().split(/\s+/).filter(Boolean).every(q=>[f.name,f.shortName,f.operator,f.city,f.country,f.summary,...f.assets.flatMap(a=>[a.name,facilityKinds[a.kind]])].join(' ').toLowerCase().includes(q)));
 const save=(navigation=false)=>onState({facilityId:selected.id,facilityAssetId:asset?.id||null,facilityView:surface,facilityFilter:{...filters}},{navigation});
 function drawList(){
  const rows=filtered();find('[data-facility-count]').textContent=rows.length+' of '+testFacilities.length+' facilities';
  find('[data-facility-clear]').hidden=!Object.values(filters).some(Boolean);
  const outside=!rows.some(f=>f.id===selected.id);find('[data-facility-filter-note]').hidden=!outside;find('[data-facility-filter-note]').textContent=outside?'The open facility is outside these filters. Select a result to change the detail view.':'';
  find('[data-facility-list]').innerHTML=rows.map(f=>'<button type="button" class="fa-facility-card" data-facility-select="'+esc(f.id)+'" aria-current="'+(f.id===selected.id?'page':'false')+'"><span class="fa-card-location">'+esc(f.country)+' · '+esc(f.city)+'</span><strong>'+esc(f.shortName||f.name)+'</strong><span class="fa-card-operator">'+esc(f.operator)+'</span><span class="fa-card-kinds">'+[...new Set(f.assets.map(a=>facilityKinds[a.kind]))].slice(0,4).map(k=>'<i>'+esc(k)+'</i>').join('')+'</span><small>'+f.assets.length+' documented systems · '+f.assets.filter(a=>a.geometry).length+' in 3D'+(f.status!=='operational'?' · '+esc(f.status):'')+'</small></button>').join('')||'<p class="fa-empty">No facilities match these filters. Try another capability or reset the filters.</p>';
 }
 const citations=(f,ids)=>'<span class="fa-citations">'+facilitySources(f,ids||[]).map(s=>link(s.url,'['+(f.sources.indexOf(s)+1)+']')).join(' ')+'</span>';
 function specifications(a,f){
  const g=a.geometry,limits=Object.entries(a.limits||{}).map(([key,value])=>{const [label,unit]=limitLabels[key]||[key,''];return [label,n(value)+' '+unit,a.limitSourceIds?.[key]];});
  const rows=[...(g?[[roles[g.dimensionRole]||g.dimensionRole,facilityDimensionsText(a),g.sourceIds]]:[]),['Usable article envelope',envelopeText(a.envelope),a.envelope?.sourceIds],...(a.door?[['Access opening',n(a.door.widthM)+' W × '+n(a.door.heightM)+' H m',a.door.sourceIds]]:[]),...limits,...(a.specifications||[]).map(s=>[s.label,s.value,s.sourceIds])];
  return '<dl class="fa-specifications">'+rows.map(([label,value,ids])=>'<div><dt>'+esc(label)+'</dt><dd>'+esc(value)+' '+(ids?citations(f,ids):'')+'</dd></div>').join('')+'</dl>';
 }
 function drawArticle({focus=false}={}){
  ticket++;viewer?.destroy();viewer=null;mapCleanup?.();mapCleanup=null;
  const f=selected,a=asset,maps=facilityMapUrls(f),assets=testFacilityAssets.filter(x=>x.facilityId===f.id),sources=facilitySources(f,[...sourceIdsFor(a),...(f.addressSourceIds||[]),...(f.location.sourceIds||[]),...(f.accessSourceIds||[])]);
  article.innerHTML='<header class="fa-place-heading"><div><div class="fa-place-location">'+icon('map-pin',14)+' '+esc(f.city)+' · '+esc(f.country)+'</div><h2 id="facility-title" tabindex="-1">'+esc(f.name)+'</h2><p>'+esc(f.operator)+'</p></div><span class="fa-operator-tag">'+esc(facilityOwnership[f.ownership])+'</span></header><p class="fa-summary">'+esc(f.summary)+'</p><div class="fa-place-actions">'+link(f.url,'Official facility website','fa-action')+'<button type="button" class="fa-action" data-facility-copy>'+icon('share-2',14)+' Copy link</button>'+(view.partId?'<button type="button" class="fa-action" data-facility-return>'+icon('box',14)+' Return to part</button>':'')+'<span data-facility-copy-status role="status"></span></div><section class="fa-equipment-panel"><header class="fa-equipment-header"><label>Test system<select data-facility-asset aria-label="Facility test system">'+assets.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===a.id?'selected':'')+'>'+esc(x.name)+' · '+esc(facilityKinds[x.kind])+(x.geometry?'':' · specifications only')+'</option>').join('')+'</select></label><div class="fa-surface-choices" role="group" aria-label="Facility view">'+[['3d','3D equipment','box'],['world','World atlas','globe'],['local','Campus map','map-pin']].map(([id,name,ic])=>'<button type="button" data-facility-surface="'+id+'" aria-pressed="'+(surface===id)+'">'+icon(ic,14)+' '+name+'</button>').join('')+'</div></header><div data-facility-surface-host></div><div class="fa-system-caption"><div><span>'+esc(facilityKinds[a.kind])+'</span><strong>'+esc(a.name)+'</strong></div><p>'+esc(a.description)+'</p></div></section><div class="fa-detail-grid"><section class="fa-info"><h3>Published capability</h3>'+specifications(a,f)+(a.envelope?.basis?'<p class="fa-note">Working volume: '+esc(a.envelope.basis)+'</p>':'')+(a.kind==='vibration'?'<p class="fa-note">The tabletop is a mounting interface. Its size alone does not establish allowable spacecraft size, mass, overturning moment, or a qualified test configuration. Large deployables normally need a specified stowed or subsystem test configuration.</p>':'')+'</section><section class="fa-info"><h3>Address & access</h3><address>'+esc(f.address)+'</address>'+citations(f,f.addressSourceIds)+'<div class="fa-map-links">'+link(maps.map,'OpenStreetMap')+' '+link(maps.directions,'Find this address')+'</div><p>'+esc(f.access||'Contact the operator to establish campaign access and availability.')+' '+citations(f,f.accessSourceIds||a.sourceIds)+'</p><dl class="fa-location-facts"><div><dt>Map locator</dt><dd>'+n(f.location.lat)+'°, '+n(f.location.lon)+'°</dd></div><div><dt>Location precision</dt><dd>'+esc(f.location.precision)+'</dd></div><div><dt>Public status</dt><dd>'+esc(f.status)+' · reviewed '+esc(f.reviewed)+'</dd></div></dl><p class="fa-note">'+esc(f.location.note)+'</p></section></div><section class="fa-info fa-model-evidence"><h3>What the model represents</h3><p>'+esc(generalModelNote(a))+'</p>'+(a.geometry?'<div class="fa-evidence-row"><span class="fa-evidence-known">Dimensioned</span><p>'+esc(a.geometry.notes)+' '+citations(f,a.geometry.sourceIds)+'</p></div><div class="fa-evidence-row"><span class="fa-evidence-assumed">Schematic</span><p>'+esc([...(a.geometry.assumptions||['Supports, skin thickness, instrumentation and ancillary details are illustrative.']),...(notional(a)?['Surrounding chamber geometry is notional; the published volume remains the dimensioned reference.']:[])].join(' '))+'</p></div>':'')+(a.modelNotes?'<p class="fa-note">'+esc(a.modelNotes)+'</p>':'')+'<p class="fa-note">A chamber vessel, room interior and thermal working envelope are different limits. No equipment geometry is expanded to accommodate a part. Unpublished capacity remains unassessed.</p></section><section class="fa-info fa-other-systems"><h3>At this campus</h3><div>'+assets.map(x=>'<button type="button" data-facility-system="'+esc(x.id)+'" aria-pressed="'+(x.id===a.id)+'"><span>'+esc(facilityKinds[x.kind])+'</span><strong>'+esc(x.name)+'</strong><small>'+esc(x.geometry?facilityDimensionsText(x):'Published capability · geometry not specified')+'</small></button>').join('')+'</div></section><section class="fa-info fa-source-section"><h3>Sources for this system & location</h3><ol>'+sources.map(s=>'<li value="'+(f.sources.indexOf(s)+1)+'">'+link(s.url,s.title)+'<small>'+esc(s.publisher||f.operator)+(s.accessed?' · accessed '+esc(s.accessed):'')+'</small>'+(s.note?'<p>'+esc(s.note)+'</p>':'')+'</li>').join('')+'</ol></section>';
  drawSurface();if(focus)find('#facility-title')?.focus({preventScroll:true});
 }
 function generalModelNote(a){return a.geometry?(notional(a)?'The published test volume or bounding dimensions are reconstructed at metric scale. The surrounding chamber, supports and services are plausible notional geometry. They are not measured installation dimensions or additional usable test space.':'A metric reconstruction of the named test system from public dimensions. Supports, skin details and ancillary equipment are notional; this is not an operator CAD file or an as-built installation drawing.'):'This capability is documented, but the record has insufficient published dimensions for a defensible 3D reconstruction. The atlas does not invent its size.';}
 async function drawSurface(){
  const mine=++ticket;viewer?.destroy();viewer=null;mapCleanup?.();mapCleanup=null;const region=find('[data-facility-surface-host]');
  host.querySelectorAll('[data-facility-surface]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.facilitySurface===surface)));
  if(surface==='local'){
   const urls=facilityMapUrls(selected);region.innerHTML='<div class="fa-campus-map" data-facility-campus></div><div class="fa-map-caption"><span>Campus locator · '+esc(selected.location.precision)+' position · equipment position is not surveyed.</span>'+link(urls.map,'Open full map')+'</div>';mapCleanup=mountFacilityMap(region.querySelector('[data-facility-campus]'),selected);return;
  }
  if(surface==='world'){drawWorld(region);return;}
  if(!asset.geometry){region.innerHTML='<div class="fa-unmodeled">'+icon('ruler',34)+'<h3>Public dimensions not recorded</h3><p>Read the capability and sources below, or choose another system at this facility to inspect its 3D reconstruction.</p></div>';return;}
  region.innerHTML='<div class="fa-model-toolbar"><div class="parts-choice" role="group" aria-label="Facility rendering">'+['materials','solid','wireframe'].map(m=>'<button type="button" data-facility-mode="'+m+'" aria-pressed="'+(settings.mode===m)+'">'+m[0].toUpperCase()+m.slice(1)+'</button>').join('')+'</div><label><input type="checkbox" data-facility-cutaway '+(settings.cutaway?'checked':'')+'> Cutaway</label><label><input type="checkbox" data-facility-dimensions '+(settings.dimensions?'checked':'')+'> Dimensions</label><label><input type="checkbox" data-facility-person '+(settings.person?'checked':'')+'> Person · 1.75 m</label></div><div class="fa-viewport" data-facility-scene><div class="fa-model-loading" role="status">Preparing dimensioned equipment…</div><div class="fa-model-stamp">'+esc(roles[asset.geometry.dimensionRole]||asset.geometry.dimensionRole)+'<strong>'+esc(facilityDimensionsText(asset))+'</strong>'+(notional(asset)?'<small>Surrounding equipment geometry is notional</small>':'')+'</div></div><div class="fa-camera-bar"><div role="group" aria-label="Facility camera presets">'+[['iso','Isometric'],['front','Front'],['side','Side'],['top','Top']].map(([id,label])=>'<button type="button" data-facility-camera="'+id+'">'+label+'</button>').join('')+'</div><button type="button" data-facility-fit>'+icon('focus',14)+' Fit equipment</button><span>Drag to orbit · Scroll to zoom · Shift-drag to pan</span></div>';
  try{
   const module=await import('./facility-viewer.js');if(!alive||ticket!==mine)return;
   const scene=find('[data-facility-scene]');viewer=module.createFacilityViewer(scene);viewer.setAsset(asset);viewer.setMode(settings.mode);viewer.setCutaway(settings.cutaway);viewer.setDimensions(settings.dimensions);if(!settings.person)viewer.setPerson(false);scene.querySelector('.fa-model-loading')?.remove();
  }catch(error){if(alive&&ticket===mine){find('.fa-model-loading').textContent='The 3D renderer could not start. Published dimensions and source records remain available below.';console.error('Facility viewer failed',error);}}
 }
 function drawWorld(region){
  const rows=filtered();region.innerHTML='<div class="fa-world" data-facility-world aria-label="World map of test facilities"><div class="fa-map-plane"><img src="./vendor/earth/day-1k.jpg" alt="" draggable="false"><div class="fa-map-graticule"></div>'+rows.map(f=>'<button type="button" class="fa-map-pin '+(f.id===selected.id?'fa-map-pin-selected':'')+'" style="left:'+((f.location.lon+180)/360*100)+'%;top:'+((90-f.location.lat)/180*100)+'%" data-facility-select="'+esc(f.id)+'" title="'+esc(f.name+' · '+f.city+', '+f.country)+'" aria-label="'+esc(f.name+' · '+f.country)+'"><span></span><b>'+esc(f.shortName||f.name)+'</b></button>').join('')+'</div><div class="fa-map-controls"><button type="button" data-facility-map-zoom="in" aria-label="Zoom world map in">+</button><button type="button" data-facility-map-zoom="out" aria-label="Zoom world map out">−</button><button type="button" data-facility-map-zoom="fit">World</button></div><span class="fa-map-world-label">'+rows.length+' LOCATIONS</span></div><div class="fa-map-caption"><span>Drag to pan · Use + / − to separate nearby campuses · Select a marker to explore.</span><small>Earth: NASA Earth Observatory / GSFC · Blue Marble: Next Generation (September 2004), Reto Stöckli · Approximate campus locators.</small></div>';
  const map=region.querySelector('[data-facility-world]'),plane=map.querySelector('.fa-map-plane');let scale=1,x=0,y=0,drag=null;
  const apply=()=>{const rect=map.getBoundingClientRect();x=clamp(x,rect.width*(1-scale),0);y=clamp(y,rect.height*(1-scale),0);plane.style.transform='translate('+x+'px,'+y+'px) scale('+scale+')';map.style.setProperty('--map-scale',scale);};
  function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
  const click=e=>{const b=e.target.closest('[data-facility-map-zoom]');if(!b)return;e.stopPropagation();const rect=map.getBoundingClientRect(),before=scale;if(b.dataset.facilityMapZoom==='fit'){scale=1;x=y=0;}else{scale=clamp(scale*(b.dataset.facilityMapZoom==='in'?1.8:1/1.8),1,18);x=rect.width/2-(rect.width/2-x)*scale/before;y=rect.height/2-(rect.height/2-y)*scale/before;}apply();};
  const down=e=>{if(e.button!==0||e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,id:e.pointerId};map.setPointerCapture(e.pointerId);},move=e=>{if(!drag)return;x+=e.clientX-drag.x;y+=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;apply();},up=()=>{drag=null;};
  map.addEventListener('click',click);map.addEventListener('pointerdown',down);map.addEventListener('pointermove',move);map.addEventListener('pointerup',up);map.addEventListener('pointercancel',up);
  mapCleanup=()=>{map.removeEventListener('click',click);map.removeEventListener('pointerdown',down);map.removeEventListener('pointermove',move);map.removeEventListener('pointerup',up);map.removeEventListener('pointercancel',up);};
 }
 function selectFacility(id){const f=getTestFacility(id);if(!f)return;selected=f;asset=testFacilityAssets.find(a=>a.facilityId===id&&a.geometry)||testFacilityAssets.find(a=>a.facilityId===id);save(true);drawList();drawArticle({focus:true});}
 const click=async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.facilitySelect){e.stopPropagation();selectFacility(b.dataset.facilitySelect);return;}
  if(b.hasAttribute('data-facility-clear')){for(const k of Object.keys(filters))filters[k]='';find('[data-facility-query]').value='';host.querySelectorAll('[data-facility-filter]').forEach(s=>s.value='');drawList();if(surface==='world')drawSurface();save();return;}
  if(b.dataset.facilitySurface){surface=b.dataset.facilitySurface;drawSurface();save();return;}
  if(b.dataset.facilitySystem){asset=getFacilityAsset(b.dataset.facilitySystem);save(true);drawArticle();return;}
  if(b.dataset.facilityMode){settings.mode=b.dataset.facilityMode;viewer?.setMode(settings.mode);host.querySelectorAll('[data-facility-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return;}
  if(b.dataset.facilityCamera){viewer?.setView(b.dataset.facilityCamera);return;}
  if(b.hasAttribute('data-facility-fit')){viewer?.fit();return;}
  if(b.hasAttribute('data-facility-return')){onPart();return;}
  if(b.hasAttribute('data-facility-copy')){const url=new URL(location.href);url.searchParams.set('reference','facilities');url.searchParams.set('facility',selected.id);url.searchParams.set('system',asset.id);url.searchParams.set('facilityView',surface);url.searchParams.delete('part');url.searchParams.delete('family');url.hash='';try{await navigator.clipboard.writeText(url.href);find('[data-facility-copy-status]').textContent='Link copied';}catch{find('[data-facility-copy-status]').textContent=url.href;}}
 };
 const input=e=>{if(e.target.hasAttribute('data-facility-query')){filters.query=e.target.value;drawList();if(surface==='world')drawSurface();save();}};
 const change=e=>{const el=e.target;
  if(el.dataset.facilityFilter){filters[el.dataset.facilityFilter]=el.value;drawList();if(surface==='world')drawSurface();save();}
  else if(el.hasAttribute('data-facility-asset')){const next=getFacilityAsset(el.value);if(next?.facilityId!==selected.id)return;asset=next;save(true);drawArticle();}
  else if(el.hasAttribute('data-facility-cutaway')){settings.cutaway=el.checked;viewer?.setCutaway(el.checked);}
  else if(el.hasAttribute('data-facility-dimensions')){settings.dimensions=el.checked;viewer?.setDimensions(el.checked);}
  else if(el.hasAttribute('data-facility-person')){settings.person=el.checked;viewer?.setPerson(el.checked);}
 };
 host.addEventListener('click',click);host.addEventListener('input',input);host.addEventListener('change',change);drawList();drawArticle();save();
 return {getSelected:()=>({facility:selected,asset}),getViewer:()=>viewer,destroy(){alive=false;ticket++;viewer?.destroy();mapCleanup?.();host.removeEventListener('click',click);host.removeEventListener('input',input);host.removeEventListener('change',change);}};
}
